export function GhostButton({
  label = "{{label}}",
  bg = "{{bg}}",
  radius = {{radius}},
  underline = {{underline}},
  disabled = {{disabled}},
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      className={underline ? "ghost-underline" : ""}
      style={{
        padding: "11px 18px",
        borderRadius: radius,
        border: "none",
        background: "transparent",
        color: bg,
        font: "600 15px/1 system-ui, sans-serif",
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.4 : 1,
      }}
    >
      {label}
    </button>
  );
}
